function setIrrelevant(){var cyl=shape.value==='cyl',wf=W.closest?W.closest('.field'):null,hf=H.closest?H.closest('.field'):null,df=D.closest?D.closest('.field'):null;if(wf){wf.dataset.v349Irrelevant=cyl?'true':'false';W.disabled=cyl;}if(hf){hf.dataset.v349Irrelevant=cyl?'true':'false';H.disabled=cyl;}if(df){df.dataset.v349Irrelevant=cyl?'false':'true';D.disabled=!cyl;}}
function packingDims(){var sv=String(shape.value||'plate'),l=num(L.value),w=num(W.value),h=num(H.value),d=num(D.value);if(sv==='cyl'){if(l<=0||d<=0)return null;return[d,d,l];}if(l<=0||w<=0||h<=0)return null;return[l,w,h];}
function packingRaw(){var dims=packingDims();if(!dims)return null;var dx=dims[0]+spacing,dy=dims[1]+spacing,dz=dims[2]+spacing,perms=[[dx,dy,dz],[dx,dz,dy],[dy,dx,dz],[dy,dz,dx],[dz,dx,dy],[dz,dy,dx]],raw=0;for(var i=0;i<perms.length;i++){var nx=Math.floor(CHX/perms[i][0]),ny=Math.floor(CHY/perms[i][1]),nz=Math.floor(CHZ/perms[i][2]);if(nx>0&&ny>0&&nz>0)raw=Math.max(raw,nx*ny*nz);}return raw>0?raw:null;}
